def reverse_array(a: list[int]) -> None:
    l, r = 0, len(a) - 1
    while l < r:
        a[l], a[r] = a[r], a[l]
        l += 1
        r -= 1

def reverse_array_rec(a: list[int], l: int = 0, r: int | None = None) -> None:
    if r is None:
        r = len(a) - 1
    if l >= r:
        return
    a[l], a[r] = a[r], a[l]
    reverse_array_rec(a, l + 1, r - 1)
